import csv,sqlite3
con=sqlite3.connect('db/satscores.db')
cur=con.execute('SELECT cds,sname,dname,AvgScrMath FROM satscores WHERE dname IN (SELECT DISTINCT dname FROM satscores WHERE LOWER(dname) LIKE "%riverside%") AND AvgScrMath > 400')
schools={r[0]:{'sname':r[1],'dname':r[2],'math':r[3]} for r in cur}
con.close()
with open('csv/frpm.csv') as f:
    dc=list(csv.DictReader(f))
    fund={r['CDSCode']:r['Charter Funding Type'] for r in dc}
result=[]
for cds,s in schools.items():
    if s['sname'] is not None:
        ft=fund.get(cds,'')
        result.append([s['sname'],ft])
print(f'Total: {len(result)}')
for r in result: print(r)

